from collections import deque

def best_hop_total(gains, k):
    best = [0] * len(gains)
    window = deque()
    for i, g in enumerate(gains):
        if window and window[0] < i - k:
            window.popleft()
        best[i] = g + (best[window[0]] if window else 0)
        while window and best[window[-1]] <= best[i]:
            window.pop()
        window.append(i)
    return best[-1]

