def best_hop_total(gains, k):
    n = len(gains)
    i = 0
    total = gains[0]
    while i < n - 1:
        if i + k >= n - 1:
            i = n - 1
        else:
            i = max(range(i + 1, i + k + 1), key=lambda j: gains[j])
        total += gains[i]
    return total

